<template><div class="page"><header><RouterLink to="/inspector">← Inspector Center</RouterLink><h1>Inspection Detail</h1><InspectorSeverityTag :value="event.severity"/></header><el-alert v-if="error" :title="error" type="error" show-icon/><template v-if="event.id"><InspectorTrace :event="event"/><div class="grid"><section><h2>Inspector Decision</h2><InspectorDecision :event="event"/></section><section><h2>Risk & Approval</h2><InspectorRisk :severity="event.severity" :requires-human="event.requiresHuman"/></section><section><h2>Issues</h2><InspectorIssueList :issues="event.issues"/></section><section><h2>Evidence</h2><InspectorEvidence :evidence="event.evidence"/></section></div><InspectorVerification :verification="event.verification"/></template><AppEmpty v-else-if="!loading&&!error" description="纠察事件不存在"/></div></template>
<script setup>import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{getInspectorEvent}from'../../api/inspector';import InspectorSeverityTag from'../../components/inspector/InspectorSeverityTag.vue';import InspectorTrace from'../../components/inspector/InspectorTrace.vue';import InspectorDecision from'../../components/inspector/InspectorDecision.vue';import InspectorRisk from'../../components/inspector/InspectorRisk.vue';import InspectorIssueList from'../../components/inspector/InspectorIssueList.vue';import InspectorEvidence from'../../components/inspector/InspectorEvidence.vue';import InspectorVerification from'../../components/inspector/InspectorVerification.vue';import AppEmpty from'../../components/common/AppEmpty.vue';const route=useRoute(),event=ref({}),loading=ref(true),error=ref('');onMounted(async()=>{try{const r=await getInspectorEvent(route.params.id);event.value=r.data||{}}catch(e){error.value=e.message}finally{loading.value=false}})</script>
<style scoped>.page{display:grid;gap:20px}header{display:flex;align-items:center;gap:16px}header h1{flex:1}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.grid section{padding:18px;background:white;border:1px solid var(--smart-border);border-radius:14px}.grid h2{margin-top:0;font-size:17px}@media(max-width:900px){.grid{grid-template-columns:1fr}}</style>
